    "teaching": {
      "nodes": [
        "N2",
        "N3"
      ],
      "reasons": {
        "N2": "用连续六个月的完整模拟数据演示需求持续性的读法。",
        "N3": "用完整成本和启动预算演示单件利润与现金分开计算。"
      },
      "deferred": [],
      "issues": [],
      "lessons": {
        "N2": {
          "node": "N2",
          "evidence_card": "同一 listing 连续六个自然月的模拟月销量估算为 340、355、380、398、412、438 件；关键词与趋势采用独立口径。",
          "method": "先对齐商品、层级和统计窗口，再看连续变化；多期证据支持观察方向，不能保证未来销量，也不等于订单。",
          "depth": "default",
          "templateOnly": false,
          "step": "demand"
        },
        "N3": {
          "node": "N3",
          "evidence_card": "虚构售价 29.90 USD；广告前贡献 8.70 USD；CPC 0.48、CVR 12%，因此 CAC 4 USD、广告后贡献 4.70 USD、保本 CVR 5.52%。",
          "method": "广告前贡献＝售价−全部非广告变动成本；CAC＝CPC÷CVR；广告后贡献＝广告前贡献−CAC。启动现金按整批单独计算。",
          "depth": "default",
          "templateOnly": false,
          "step": "profit"
        }
      },
      "skippedAll": false,
      "templates": {
        "N1": {
          "title": "数据口径",
          "goal": "看清一条销量数据回答的是哪个问题：整款还是单规格、哪一个统计窗口、估算还是真实订单。",
          "rule": "同一父体、同一窗口的整款销量只算一次；窗口、层级、规格不同的数字不能直接相加或比较；估算值不等于订单。",
          "misread": "把多个子体行里重复出现的整款月销相加，得到被放大的“总销量”。",
          "verify": "回到数据来源，核对每条销量的统计起止日期、销量层级（整款/子体）和估算性质。"
        },
        "N2": {
          "title": "需求证据",
          "goal": "区分“某个窗口卖得多”和“需求持续存在”，并在缺少历史时保留判断。",
          "rule": "单个窗口的销量只说明该窗口的估算表现；判断持续性需要连续、口径一致的多期数据；缺少历史时把持续性记为未知。",
          "misread": "看到单月高销量就判断需求会持续增长。",
          "verify": "补充同一商品、同一层级、连续多个窗口的销量或排名历史，再看方向和波动。"
        },
        "N3": {
          "title": "利润边界",
          "goal": "理解广告获客成本如何随转化率变化，以及它怎样改变单件贡献利润。",
          "rule": "广告获客成本 CAC = CPC ÷ CVR；广告后贡献 = 广告前贡献 − CAC；保本转化率 = CPC ÷ 广告前贡献。成本或转化率的假设一变，结论可能反转。",
          "misread": "只用售价减采购价判断利润，漏掉广告、物流、平台费和退货。",
          "verify": "逐项核对已计入与未计入的成本，并用实际广告报告或同类商品的 CPC、CVR 校准假设。"
        }
      }
    },
