                "figure_id": "F_post",
                "how_to_read": "29.90 − 8 − 7.30 − 4.49 − 0.90 − 0.51 − 0.48 ÷ 0.12 = 4.70 USD。",
                "verify": "真实任务中用正式报价与广告表现替换模拟假设。"
