            "interpretation": [
              "售价设为 29.90 USD，采购 8 USD；物流 7.30 USD 包含 FBA 履约 4、头程 2、关税 0.80 和贴标 0.50。再扣平台费 4.49、退货预留 0.90 与其他变动成本 0.51 后，广告前贡献为 8.70 USD。这比仅用售价减采购价更接近单件经营余量。",
              "按 CPC 0.48 USD 和 CVR 12% 的预设，CAC 为 4 USD，广告后每件贡献 4.70 USD，保本转化率为 5.52%。CVR 减半到 6% 时贡献仅剩 0.70 USD，说明方案对广告转化较敏感；首批应控制投放节奏，用真实点击、订单与退货替换假设后再扩大。"
            ],
