              "生产运输 35 天、库存周转 45 天、回款等待 14 天，合计现金周期假设 94 天。预算余量用于应对实际动销、退货与补货的不确定性，不建议一次全部投入。单件成本按每件摊销，启动现金按整批占用记录，同一费用在各自口径内只计一次。"
