    "quantity": "120 件是这份模拟案例设定的首批方案，不是根据市场销量自动预测出的最佳数量。它对应供应商 A 的 MOQ，采购 8 USD × 120 = 960 USD；加上头程、税费、贴标、广告和其他启动支出后，共占用 2,966 USD，5,000 USD 预算还剩 2,034 USD。\n\n因此建议是先做能被预算覆盖的小批量试销。真实任务中需要用你实际拿到的 MOQ、报价、预算和周转安排重算，不能因为案例写了 120 就照搬。",
